package order

// CalculeTotalTTC calcule le montant TTC à partir du montant HT en centimes
// et du taux de TVA en pour mille (‰).
//
// Exemple : HT = 10000 cents (100 €), TVA = 200‰ (20%) → TTC = 12000 cents (120 €).
//
// L'arrondi se fait au centime le plus proche (round half-up).
func CalculeTotalTTC(htCents, tvaPpm int64) int64 {
	if htCents < 0 || tvaPpm < 0 {
		return 0
	}

	// Formule : TTC = HT × (1000 + TVA‰) / 1000
	// On ajoute 500 avant la division pour un arrondi au centime le plus proche.
	numerator := htCents*(1000+tvaPpm) + 500
	return numerator / 1000
}
```

